/// SOUND_LogarithmicSearch(table, count, lo, hi, value): recursive bisection returning the
/// register of the entry whose value bracket contains `value` (below -> the lower entry).
pub fn SOUND_LogarithmicSearch(t: &[(u32, f32)], count: u32, lo: u32, hi: u32, v: f32) -> u32 {
    let m = lo + ((hi - lo) >> 1);
    let e = t[m as usize];
    if v == e.1 {
        e.0
    } else if v < e.1 {
        if m == 0 { t[0].0 } else if t[m as usize - 1].1 <= v { t[m as usize - 1].0 } else { SOUND_LogarithmicSearch(t, count, lo, m, v) }
    } else if m == count - 1 {
        t[count as usize - 1].0
    } else if v < t[m as usize + 1].1 {
        t[m as usize + 1].0
    } else {
        SOUND_LogarithmicSearch(t, count, m, hi, v)
    }
}

pub fn SOUND_GetRandomAttackValue(s: &str, rng: &mut Rand) -> u32 { SOUND_LogarithmicSearch(&G_ATTACK_RATE, 100, 0, 100, SOUND_ComputeRandomizedValue(s, rng)) }
pub fn SOUND_GetRandomDecayValue(s: &str, rng: &mut Rand) -> u32 { SOUND_LogarithmicSearch(&G_DECAY_RATE, 16, 0, 16, SOUND_ComputeRandomizedValue(s, rng)) }
pub fn SOUND_GetRandomSustainLevelValue(s: &str, rng: &mut Rand) -> u32 { SOUND_LogarithmicSearch(&G_SUSTAIN_LEVEL_RATE, 16, 0, 16, SOUND_ComputeRandomizedValue(s, rng)) }
/// "-1" -> gSustainRate[108].reg (no random draw).
pub fn SOUND_GetRandomSustainRateValue(s: &str, rng: &mut Rand) -> u32 {
    if s == "-1" { return G_SUSTAIN_RATE_RATE[108].0; }
    SOUND_LogarithmicSearch(&G_SUSTAIN_RATE_RATE, 0x6d, 0, 0x6d, SOUND_ComputeRandomizedValue(s, rng))
}
pub fn SOUND_GetRandomReleaseRateValue(s: &str, rng: &mut Rand) -> u32 { SOUND_LogarithmicSearch(&G_RELEASE_RATE, 0x1b, 0, 0x1b, SOUND_ComputeRandomizedValue(s, rng)) }

/// SOUND_GetFinalADSROfSample: low 16 bits = ADSR1, high 16 bits = ADSR2 (draw order A,D,SL,SR,R).
pub fn SOUND_GetFinalADSROfSample(p: &SbhPlayback, rng: &mut Rand) -> u32 {
    let a = SOUND_GetRandomAttackValue(&p.attack, rng);
    let d = SOUND_GetRandomDecayValue(&p.decay, rng);
    let sl = SOUND_GetRandomSustainLevelValue(&p.sustain_level, rng);
    let sr = SOUND_GetRandomSustainRateValue(&p.sustain_rate, rng);
    let r = SOUND_GetRandomReleaseRateValue(&p.release, rng);
    (a & 0x7f) << 8 | 0x8000 | (d & 0xf) << 4 | sl & 0xf | (sr & 0x7f) << 0x16 | 0xc000_0000 | (r & 0x1f) << 0x10 | 0x20_0000
}

/// SPU envelope phase step (Nocash "ADSR"): returns the new level.
struct Phase { exp: bool, dec: bool, shift: i32, step: i32 }
fn tick(p: &Phase, level: i32, counter: &mut u32) -> i32 {
    let mut cycles = 1u32 << (p.shift - 11).max(0);
    let mut step = p.step << (11 - p.shift).max(0);
    if p.exp && !p.dec && level > 0x6000 { cycles *= 4; }
    if p.exp && p.dec { step = step * level >> 15; }
    *counter += 1;
    if *counter >= cycles { *counter = 0; (level + step).clamp(0, 0x7fff) } else { level }
}

/// SPU2 envelope for `adsr` (SOUND_GetFinalADSROfSample layout), one value (0..1) per 48 kHz
/// tick, key-off at `key_off` ticks (None = held).
pub fn envelope(adsr: u32, ticks: usize, key_off: Option<usize>) -> Vec<f32> {
    let (a1, a2) = (adsr & 0xffff, adsr >> 16);
    let attack = Phase { exp: a1 & 0x8000 != 0, dec: false, shift: ((a1 >> 10) & 0x1f) as i32, step: 7 - ((a1 >> 8) & 3) as i32 };
    let decay = Phase { exp: true, dec: true, shift: ((a1 >> 4) & 0xf) as i32, step: -8 };
    let sl = (((a1 & 0xf) + 1) * 0x800) as i32;
    let sdec = a2 & 0x4000 != 0;
    let sstep = (a2 >> 6) & 3;
    let sustain = Phase { exp: a2 & 0x8000 != 0, dec: sdec, shift: ((a2 >> 8) & 0x1f) as i32, step: if sdec { -8 + sstep as i32 } else { 7 - sstep as i32 } };
    let release = Phase { exp: a2 & 0x20 != 0, dec: true, shift: (a2 & 0x1f) as i32, step: -8 };
    let (mut level, mut phase, mut c) = (0i32, 0u8, 0u32);
    (0..ticks).map(|t| {
        if Some(t) == key_off { phase = 3; c = 0; }
        level = match phase {
            0 => { let l = tick(&attack, level, &mut c); if l >= 0x7fff { phase = 1; c = 0; } l }
            1 => { let l = tick(&decay, level, &mut c); if l <= sl { phase = 2; c = 0; } l }
            2 => tick(&sustain, level, &mut c),
            _ => tick(&release, level, &mut c),
        };
        level as f32 / 32767.0
    }).collect()
}

/// Apply the SPU envelope to decoded PCM played at `rate` Hz * `pitch` (48 kHz SPU ticks).
pub fn apply_adsr(pcm: &[i16], rate: u32, pitch: f32, adsr: u32, key_off: Option<usize>) -> Vec<i16> {
    let step = rate as f64 * pitch as f64 / 48000.0;
    let ticks = if step > 0.0 { (pcm.len() as f64 / step).ceil() as usize } else { 0 };
    let env = envelope(adsr, ticks.max(1), key_off);
    pcm.iter().enumerate().map(|(i, &s)| {
        let t = ((i as f64 / step.max(1e-9)) as usize).min(env.len() - 1);
        (s as f32 * env[t]) as i16
    }).collect()
}
